  "ev.hsn6": "आइटेम {n}: ई-इनभइसआव 6 एबा 8 अंकनि HSN/SAC कोड नांगोन (4 अंकआ ₹5 क्रर बिनिख्रुइ खम बिजिनेसनि थाखायल, जाय ई-इनभइस बानायाखै)।",
  "ev.old30": "बे इनभइसआ 30 एबा बांसिन सान गोजाम। ₹10 क्रर एबा बांसिन टर्नओभाराव पर्टालआ बेखौ दा रेजिस्टार खालामा। गोदान इनभइस बानायनायनि सिगाङाव नोंनि एकाउन्टेन्टखौ सों।",
  "ev.lt5": "ई-इनभइसआ नोंनि थाखाय गोनांथार नङा, जेब्ला सिम 2017-18 निफ्राय मोनसे बोसोराव नोंनि टर्नओभारआ ₹5 क्रर बारायाखै।",
  "ev.old180": "180 सान बिनिख्रुइ गोजाम डकुमेन्टनि ई-वे बिलखौ पर्टालआ बानाया।",
  "ev.smallst": "{st} नि सिङाव ई-वे बिलआ सरासनथि ₹{v} बिनिख्रुइ गोजौआवल नांगौ (गुबुन राज्याव ₹50,000 बिनिख्रुइ गोजौ; गुबुन राज्याव थांनाय जब वार्क आरो हेन्डिक्राफ्टआव जायखिजाय बिथोराव नांगौ)।",
  "ev.fromirn": "नोंनि बिजिनेसआ ई-इनभइस बानायनो नांब्ला, बे इनभइसनि ई-वे बिलखौ पर्टालआ बेनि IRN निफ्रायल बानायो: “ई-इनभइसजों लोगोसे ई-वे बिलबो बानाय” आव टिक हो आरो ई-इनभइस फाइल बानाय।",
