  "b2.gain": "मुनाफा {a}: एकाउन्टेन्टखौ सों",
  "b2.farules": "डेप्रिसियेसनखौ माबोरै हिसाब खालामो",
  "b2.farule1": "खातानि डेप्रिसियेसना कम्पानिज एक्ट, 2013 नि सेडिउल II बादियै: एसेट रोखोम गासैनि मोनसे बाहायनाय बिबां दं (बिदिन्थि कम्पिउटार 3 बोसोर, फार्निसार 10 बोसोर, प्लान्ट आरो मेसिनारि 15 बोसोर, कार 8 बोसोर), बाकि बेसेना सरासनस्रा बेसेननि 5% निख्रुइ बांसिन जाया, आरो बोसोरनि गेजेराव दाजाबनाय एबा फाननाय एसेटआव बाहायनाय सानफोरनि डेप्रिसियेसनल' गोनां। स्ट्रेट लाइन (SLM: बोसोर गासै समान रां) एबा रिटन डाउन भेलु (WDV: बाकि रांआव थिरां रेट) सायख। प्रपराइटर आरो फार्मफोरा बांसिनयावनो बे आदबखौ बाहायो; थागा नोंथांनि एकाउन्टेन्टनि।",
  "b2.farule2": "इनकाम टेक्स डेप्रिसियेसन ब्लक गासैनि गुबुन गुबुनै हिसाब जायो: ब्लक रेटआव रिटन डाउन भेलु (बिदिन्थि प्लान्ट आरो मेसिनारि 15%, फार्निसार 10%, कम्पिउटार 40%), बोसोराव 180 सान निख्रुइ खम बाहायनाय एसेटआव खावसे रेट, आरो फान्नायनि रांआ ब्लक निफ्राय खमायो। बेयो इनकाम टेक्स रिटार्ननि थाखायल', खाताआव माबेलाबो होआ। फुं होनाय रेटफोरा सरासनस्रा ब्लक रेट: नोंथांनि एकाउन्टेन्टजों थारथि खालाम, जोबोद 1 एप्रिल 2026 निफ्राय इनकाम-टेक्स एक्ट, 2025 नि सिंआव थानाय बोसोरफोरनि थाखाय।",
  "b2.farule3": "नोंथाङा 'डेप्रिसियेसन हो' नेबब्लाल' डेप्रिसियेसना खाताआव थांयो: बोसोरनि जोबनाय सान (एबा बोसोरनि गेजेराव दिनै) नि जार्नाल एन्ट्रिआ डेप्रिसियेसनखौ डेबिट खालामो आरो एसेट गासैखौ खमायो। उनाव एसेट सोलायोब्ला फिन हो, फारागल' दाजाबगोन।",
